1	// The low-level HMAC functions (HMAC_CTX_new/HMAC_Init_ex/HMAC_Update/
2	// HMAC_Final) are available in both OpenSSL 1.1.1 and OpenSSL 3.x.
3	// OpenSSL 3.x marks them deprecated in favour of the EVP_MAC interface
4	// (which 1.1.1 does not have); suppress those deprecation warnings so the
5	// portable interface builds cleanly on 3.x. The streaming Init/Update/
6	// Final form lets the message file be digested in fixed-size chunks
7	// instead of being held in memory all at once.
8	#define OPENSSL_SUPPRESS_DEPRECATED
9	#include <openssl/evp.h>
10	#include <openssl/hmac.h>
11	
12	#include <array>
13	#include <cerrno>
14	#include <cstddef>
15	#include <csignal>
16	#include <cstring>
17	#include <fstream>
18	#include <iostream>
19	#include <map>
20	#include <memory>
21	#include <string>
22	#include <string_view>
23	#include <vector>
24	
25	#include <unistd.h>
26	
27	namespace {
28	
29	constexpr std::string_view kTagUsage =
30	    "Usage: messagetag tag --key-hex <hex-key> --file <message-file>\n";
31	
32	constexpr std::string_view kVerifyUsage =
33	    "Usage: messagetag verify --key-hex <hex-key> --file <message-file> "
34	    "--tag-hex <hex-tag>\n";
35	
36	// Per-command identity for the shared option/prepare/authenticate flow:
37	// the name spliced into diagnostics, that command's own usage line and
38	// exactly the value-taking options it accepts. Whether a token following
39	// an option counts as "missing a value" is decided against this list, so
40	// each command keeps judging missing values by its own option set and a
41	// diagnostic for one command never carries the other command's usage.
42	struct CommandSpec {
43	    std::string_view name;
44	    std::string_view usage;
45	    std::vector<std::string_view> options;
46	};
47	
48	const CommandSpec& tagSpec() {
49	    static const CommandSpec spec{
50	        "tag", kTagUsage, {"--key-hex", "--file"}};
51	    return spec;
52	}
53	
54	const CommandSpec& verifySpec() {
55	    static const CommandSpec spec{
56	        "verify", kVerifyUsage,
57	        {"--key-hex", "--file", "--tag-hex"}};
58	    return spec;
59	}
60	
61	// SHA-256 HMAC tags are always 32 bytes / 64 hex characters.
62	constexpr std::size_t kTagBytes = 32;
63	
64	// Decode hexadecimal into raw bytes: every two characters are one byte and
65	// leading zeros must be preserved (e.g. "0001" is two bytes, not the number
66	// 1). Only digits and a-f/A-F are accepted; empty input, odd length,
67	// whitespace and a 0x prefix are rejected.
68	bool decodeHex(std::string_view hex, std::vector<unsigned char>& bytes) {
69	    if (hex.empty() || hex.size() % 2 != 0) {
70	        return false;
71	    }
72	    auto nibble = [](char c) -> int {
73	        if (c >= '0' && c <= '9') return c - '0';
74	        if (c >= 'a' && c <= 'f') return c - 'a' + 10;
75	        if (c >= 'A' && c <= 'F') return c - 'A' + 10;
76	        return -1;
77	    };
78	    bytes.clear();
79	    bytes.reserve(hex.size() / 2);
80	    for (std::size_t i = 0; i < hex.size(); i += 2) {
81	        int hi = nibble(hex[i]);
82	        int lo = nibble(hex[i + 1]);
83	        if (hi < 0 || lo < 0) {
84	            return false;
85	        }
86	        bytes.push_back(static_cast<unsigned char>((hi << 4) | lo));
87	    }
88	    return true;
89	}
90	
91	std::string hexEncode(const unsigned char* data, std::size_t length) {
92	    static constexpr char kHex[] = "0123456789abcdef";
93	    std::string out;
94	    out.resize(length * 2);
95	    for (std::size_t i = 0; i < length; ++i) {
96	        out[2 * i] = kHex[data[i] >> 4];
97	        out[2 * i + 1] = kHex[data[i] & 0x0F];
98	    }
99	    return out;
100	}
101	
102	// Write every byte of the one-line success result to file descriptor 1.
103	// This deliberately bypasses std::cout: the write can fail while the
104	// stream buffer is flushed, i.e. after the program has already "printed"
105	// the whole line. A short write of the remaining bytes is continued (pipes
106	// and space-constrained files legitimately accept partial counts); only
107	// EINTR is retried after a failed call, so EPIPE/ENOSPC/EIO terminate the
108	// attempt immediately. Bytes already accepted by the kernel cannot be
109	// taken back and are not re-emitted.
110	bool writeAllFd(int fd, std::string_view data) {
111	    std::size_t written = 0;
112	    while (written < data.size()) {
113	        ssize_t n = ::write(fd, data.data() + written, data.size() - written);
114	        if (n > 0) {
115	            written += static_cast<std::size_t>(n);
116	            continue;
117	        }
118	        if (n < 0 && errno == EINTR) {
119	            continue;
120	        }
121	        return false;
122	    }
123	    return true;
124	}
125	
126	// Output the single success line and make the exit code depend on it: a
127	// correctly computed tag, or a passed comparison, is not success unless
128	// the complete line (including the trailing newline) has actually reached
129	// standard output. On failure emits exactly one diagnostic that names the
130	// result-output stage -- never the key, the supplied tag or a recomputed
131	// tag -- and returns false so the caller exits 1. The errno text is saved
132	// before anything else can clobber errno.
133	bool emitResultLine(std::string_view command, std::string_view line) {
134	    if (writeAllFd(STDOUT_FILENO, line)) {
135	        return true;
136	    }
137	    int savedErrno = errno;
138	    // One single line, naming only the result-output stage. No key, tag or
139	    // recomputed tag is referenced, and no usage text follows.
140	    std::cerr << "messagetag " << command
141	              << ": error: standard output write failed while outputting "
142	                 "the result (" << std::strerror(savedErrno) << ")\n";
143	    return false;
144	}
145	
146	// Parse options of the form "--name value" starting at argv[2]. On a usage
147	// problem (an unknown argument, or an option without a following value) a
148	// command-specific diagnostic and the usage line are written to stderr and
149	// this returns false; the caller then exits with code 2. On success the
150	// collected values are stored keyed by option name, and the caller checks
151	// which required options are present. Only the value-taking options named
152	// in `names` are accepted.
153	//
154	// An option's value is missing not only when nothing follows it, but also
155	// when the next token is itself one of this command's option names: in
156	// "--file --file" the second "--file" is another option, not a file name,
157	// so the first "--file" is reported as missing a value instead of
158	// consuming the option as its value. Only an exact match with a recognized
159	// option name triggers this; any other token (including one that merely
160	// starts with a dash, such as "--notes", and including an explicitly empty
161	// string) is taken as the value, so file paths with leading dashes stay
162	// usable and empty values keep their own distinct diagnostics.
163	bool parseValueOptions(const CommandSpec& spec, int argc, char* argv[],
164	                       std::map<std::string, std::string>& values) {
165	    auto isOptionName = [&spec](std::string_view arg) {
166	        for (std::string_view name : spec.options) {
167	            if (arg == name) {
168	                return true;
169	            }
170	        }
171	        return false;
172	    };
173	    for (int i = 2; i < argc; ++i) {
174	        std::string arg(argv[i]);
175	        if (!isOptionName(arg)) {
176	            std::cerr << "messagetag " << spec.name
177	                      << ": error: unknown argument '" << arg << "'\n"
178	                      << spec.usage;
179	            return false;
180	        }
181	        // The diagnostic names only the option that lacks a value; the
182	        // following token (a recognized option name, or nothing at all) is
183	        // never spliced into the message, and neither is any key or tag
184	        // material supplied elsewhere on the command line.
185	        if (i + 1 >= argc || isOptionName(argv[i + 1])) {
186	            std::cerr << "messagetag " << spec.name
187	                      << ": error: option '" << arg
188	                      << "' requires a value\n"
189	                      << spec.usage;
190	            return false;
191	        }
192	        values[arg] = argv[++i];
193	    }
194	    return true;
195	}
196	
197	bool requireOption(const CommandSpec& spec,
198	                   const std::map<std::string, std::string>& values,
199	                   std::string_view name) {
200	    if (values.find(std::string(name)) == values.end()) {
201	        std::cerr << "messagetag " << spec.name
202	                  << ": error: missing required option '" << name << "'\n"
203	                  << spec.usage;
204	        return false;
205	    }
206	    return true;
207	}
208	
209	// Decode the --key-hex argument, emitting the shared key-format diagnostic
210	// (which never echoes the submitted key) on failure.
211	bool parseKey(const CommandSpec& spec, const std::string& keyHex,
212	              std::vector<unsigned char>& key) {
213	    if (decodeHex(keyHex, key)) {
214	        return true;
215	    }
216	    std::cerr << "messagetag " << spec.name
217	              << ": error: invalid --key-hex: expected a non-empty, "
218	                 "even-length string of hexadecimal characters (0-9, a-f, A-F); "
219	                 "every two characters denote one key byte and leading zeros must "
220	                 "be kept; a 0x prefix and whitespace are not accepted\n"
221	              << spec.usage;
222	    return false;
223	}
224	
225	// Stream the message file into HMAC-SHA-256 a fixed-size chunk at a time.
226	// The message is never stored whole: regardless of file length, only one
227	// 64 KiB read buffer is needed on top of the constant-size HMAC context.
228	//
229	// The bytes are not interpreted as text: the file is opened in binary mode,
230	// trailing newlines are kept, line endings are not converted and zero bytes
231	// are preserved. An empty file simply yields no Update calls, which
232	// authenticates the empty message.
233	enum class HmacStatus { kSuccess, kReadError, kCryptoError };
234	
235	HmacStatus hmacSha256File(const std::vector<unsigned char>& key,
236	                          const std::string& path,
237	                          std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
238	                          std::size_t& macLength) {
239	    HMAC_CTX* rawCtx = HMAC_CTX_new();
240	    if (rawCtx == nullptr) {
241	        return HmacStatus::kCryptoError;
242	    }
243	    std::unique_ptr<HMAC_CTX, decltype(&HMAC_CTX_free)> ctx(rawCtx,
244	                                                            HMAC_CTX_free);
245	
246	    // Init with the key and SHA-256. HMAC_Init_ex performs the standard
247	    // RFC 2104 key normalization itself, so keys longer than the SHA-256
248	    // block size are hashed exactly as the standard requires; the resulting
249	    // tag is identical to the one-shot HMAC() interface on both OpenSSL
250	    // 1.1.1 and OpenSSL 3.x. The key is validated to be non-empty before
251	    // this is called, so key.data() is always valid.
252	    if (HMAC_Init_ex(ctx.get(), key.data(), static_cast<int>(key.size()),
253	                     EVP_sha256(), nullptr) != 1) {
254	        return HmacStatus::kCryptoError;
255	    }
256	
257	    std::ifstream in(path, std::ios::binary | std::ios::in);
258	    if (!in) {
259	        return HmacStatus::kReadError;
260	    }
261	
262	    std::array<char, 65536> buffer{};
263	    while (in.read(buffer.data(), static_cast<std::streamsize>(buffer.size()))) {
264	        if (HMAC_Update(ctx.get(),
265	                        reinterpret_cast<const unsigned char*>(buffer.data()),
266	                        static_cast<std::size_t>(in.gcount())) != 1) {
267	            return HmacStatus::kCryptoError;
268	        }
269	    }
270	    // A read error (including one that happens after part of the message has
271	    // already been fed to HMAC) aborts authentication: Final is never called,
272	    // so no partial-message tag can be produced. EOF with a short final read
273	    // is normal and those remaining bytes must still participate.
274	    if (in.bad()) {
275	        return HmacStatus::kReadError;
276	    }
277	    if (in.gcount() > 0) {
278	        if (HMAC_Update(ctx.get(),
279	                        reinterpret_cast<const unsigned char*>(buffer.data()),
280	                        static_cast<std::size_t>(in.gcount())) != 1) {
281	            return HmacStatus::kCryptoError;
282	        }
283	    }
284	
285	    unsigned int outLength = 0;
286	    if (HMAC_Final(ctx.get(), mac.data(), &outLength) != 1) {
287	        return HmacStatus::kCryptoError;
288	    }
289	    macLength = outLength;
290	    return HmacStatus::kSuccess;
291	}
292	
293	// Output of the shared preparation stage that the command-specific
294	// decision still needs afterwards.
295	struct PreparedAuthentication {
296	    // verify only: the supplied --tag-hex decoded to 32 bytes; unused by
297	    // tag, which has no tag to compare against.
298	    std::vector<unsigned char> expectedTag;
299	};
300	
301	// Prepare and perform the message authentication that both commands share.
302	// This is the single place that maintains the ordered checks leading up to
303	// the command-specific result:
304	//
305	//   1. parse exactly this command's value-taking options (unknown argument
306	//      or missing value -> exit 2 with that command's usage);
307	//   2. require --key-hex/--file, and additionally --tag-hex when
308	//      `expectTag` is set (exit 2);
309	//   3. decode the key, and the supplied tag for verify, BEFORE the message
310	//      file is opened, so a malformed key/tag is a parameter error (exit 2)
311	//      even when the file does not exist;
312	//   4. stream the whole file through HMAC-SHA-256 (read or computation
313	//      failure -> exit 1, with no result produced; a prefix read before a
314	//      failure is never finalized as the message).
315	//
316	// Every diagnostic goes out from here under the failing command's own name
317	// and usage, so one and the same failure behaviour no longer has to be kept
318	// in sync between runTag and runVerify. Returns the process exit code; on
319	// success it is 0 and `mac`/`macLength` (plus `prepared` for verify) hold
320	// what the caller needs for its own result handling; otherwise the caller
321	// returns the non-zero code unchanged.
322	int prepareAuthentication(const CommandSpec& spec, int argc, char* argv[],
323	                          bool expectTag,
324	                          std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
325	                          std::size_t& macLength,
326	                          PreparedAuthentication& prepared) {
327	    std::map<std::string, std::string> opts;
328	    if (!parseValueOptions(spec, argc, argv, opts)) {
329	        return 2;
330	    }
331	    if (!requireOption(spec, opts, "--key-hex") ||
332	        !requireOption(spec, opts, "--file") ||
333	        (expectTag && !requireOption(spec, opts, "--tag-hex"))) {
334	        return 2;
335	    }
336	    const std::string& keyHex = opts["--key-hex"];
337	    const std::string& filePath = opts["--file"];
338	
339	    // All input-format checks happen before the file is opened, so a
340	    // malformed key or tag is reported as a parameter error (exit 2) even
341	    // when the message file does not exist.
342	    std::vector<unsigned char> key;
343	    if (!parseKey(spec, keyHex, key)) {
344	        return 2;
345	    }
346	
347	    if (expectTag) {
348	        // The supplied tag must decode to exactly 32 bytes (64 hex
349	        // characters); decodeHex already rejects empty input, odd length,
350	        // non-hex characters and whitespace, which also rules out a 0x
351	        // prefix. The submitted tag is deliberately not echoed back.
352	        if (!decodeHex(opts["--tag-hex"], prepared.expectedTag) ||
353	            prepared.expectedTag.size() != kTagBytes) {
354	            std::cerr << "messagetag " << spec.name
355	                      << ": error: invalid --tag-hex: expected exactly 64 "
356	                         "hexadecimal characters denoting 32 bytes (0-9, a-f, "
357	                         "A-F); empty, truncated or over-long values, embedded "
358	                         "whitespace and a 0x prefix are not accepted\n"
359	                      << spec.usage;
360	            return 2;
361	        }
362	    }
363	
364	    switch (hmacSha256File(key, filePath, mac, macLength)) {
365	        case HmacStatus::kReadError:
366	            // The partially read prefix must never be authenticated as if it
367	            // were the whole message.
368	            std::cerr << "messagetag " << spec.name
369	                      << ": error: failed to read file: " << filePath << "\n";
370	            return 1;
371	        case HmacStatus::kCryptoError:
372	            std::cerr << "messagetag " << spec.name
373	                      << ": error: HMAC-SHA-256 computation failed\n";
374	            return 1;
375	        case HmacStatus::kSuccess:
376	            return 0;
377	    }
378	    return 1;  // unreachable: every status is handled above
379	}
380	
381	int runTag(int argc, char* argv[]) {
382	    std::array<unsigned char, EVP_MAX_MD_SIZE> mac{};
383	    std::size_t macLength = 0;
384	    PreparedAuthentication prepared;
385	    int rc = prepareAuthentication(tagSpec(), argc, argv, /*expectTag=*/false,
386	                                   mac, macLength, prepared);
387	    if (rc != 0) {
388	        return rc;
389	    }
390	
391	    std::string tagLine = hexEncode(mac.data(), macLength);
392	    tagLine.push_back('\n');
393	    // Exit 0 only once the whole line is confirmed written; a correct tag
394	    // does not make a failed/partial result output a success.
395	    if (!emitResultLine("tag", tagLine)) {
396	        return 1;
397	    }
398	    return 0;
399	}
400	
401	// Compare two fixed-length byte strings without leaking the length of any
402	// matching prefix: the loop always touches every byte and accumulates all
403	// differences, so the running time does not depend on where (or whether)
404	// the inputs differ.
405	bool constantTimeEqual(const unsigned char* a, const unsigned char* b,
406	                       std::size_t length) {
407	    unsigned char diff = 0;
408	    for (std::size_t i = 0; i < length; ++i) {
409	        diff |= static_cast<unsigned char>(a[i] ^ b[i]);
410	    }
411	    return diff == 0;
412	}
413	
414	int runVerify(int argc, char* argv[]) {
415	    std::array<unsigned char, EVP_MAX_MD_SIZE> mac{};
416	    std::size_t macLength = 0;
417	    PreparedAuthentication prepared;
418	    int rc = prepareAuthentication(verifySpec(), argc, argv,
419	                                   /*expectTag=*/true, mac, macLength,
420	                                   prepared);
421	    if (rc != 0) {
422	        return rc;
423	    }
424	
425	    if (macLength != kTagBytes ||
426	        !constantTimeEqual(mac.data(), prepared.expectedTag.data(),
427	                           kTagBytes)) {
428	        // State only that authentication failed; do not assign a cause (the
429	        // message, the key or the tag could each be the one that differs),
430	        // and never print the recomputed tag, a matched prefix or the key.
431	        std::cerr << "messagetag verify: error: authentication tag mismatch: "
432	                     "the supplied tag does not match the given key and file "
433	                     "content\n";
434	        return 3;
435	    }
436	
437	    // Exit 0 only once the whole "OK\n" line is confirmed written; a
438	    // passed comparison does not make a failed/partial result output a
439	    // success.
440	    if (!emitResultLine("verify", "OK\n")) {
441	        return 1;
442	    }
443	    return 0;
444	}
445	
446	}  // namespace
447	
448	int main(int argc, char* argv[]) {
449	    if (argc == 2 && std::string_view(argv[1]) == "--version") {
450	        std::cout << "messagetag 0.1.0\n";
451	        return 0;
452	    }
453	    if (argc >= 2 && (std::string_view(argv[1]) == "tag" ||
454	                      std::string_view(argv[1]) == "verify")) {
455	        // A closed downstream pipe must surface as an EPIPE write failure
456	        // (reported and mapped to exit 1), not as the default SIGPIPE kill,
457	        // which would leave the shell with a signal-terminated status and
458	        // no diagnostic. Ignore SIGPIPE so write(2) returns EPIPE instead.
459	        std::signal(SIGPIPE, SIG_IGN);
460	        if (std::string_view(argv[1]) == "tag") {
461	            return runTag(argc, argv);
462	        }
463	        return runVerify(argc, argv);
464	    }
465	    std::cerr << "Usage: messagetag --version\n"
466	              << "       messagetag tag --key-hex <hex-key> "
467	                 "--file <message-file>\n"
468	              << "       messagetag verify --key-hex <hex-key> "
469	                 "--file <message-file> --tag-hex <hex-tag>\n";
470	    return 2;
471	}
