```cpp
// Streaming HMAC-SHA-256 context shared by the file and standard-input
// sources: both feed their message bytes through identical Init/Update/
// Final calls, so the same bytes always produce the same tag regardless of
// where they were read from. Init with the key happens once at
// construction; HMAC_Init_ex performs the standard RFC 2104 key
// normalization itself, so keys longer than the SHA-256 block size are
// hashed exactly as the standard requires and the tag is identical to the
// one-shot HMAC() interface on both OpenSSL 1.1.1 and OpenSSL 3.x. The key
// is validated to be non-empty before this is constructed, so key.data()
// is always valid.
class HmacSha256Stream {
  public:
    explicit HmacSha256Stream(const std::vector<unsigned char>& key)
        : ctx_(HMAC_CTX_new(), &HMAC_CTX_free) {
        usable_ = ctx_ != nullptr &&
                  HMAC_Init_ex(ctx_.get(), key.data(),
                               static_cast<int>(key.size()), EVP_sha256(),
                               nullptr) == 1;
    }

    bool usable() const { return usable_; }

    bool update(const char* data, std::size_t length) {
        return HMAC_Update(ctx_.get(),
                           reinterpret_cast<const unsigned char*>(data),
                           length) == 1;
    }

    bool finish(std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
                std::size_t& macLength) {
        unsigned int outLength = 0;
        if (HMAC_Final(ctx_.get(), mac.data(), &outLength) != 1) {
            return false;
        }
        macLength = outLength;
        return true;
    }

  private:
    std::unique_ptr<HMAC_CTX, decltype(&HMAC_CTX_free)> ctx_;
    bool usable_ = false;
};
```

