HmacStatus hmacSha256File(const std::vector<unsigned char>& key,
                          const std::string& path,
                          std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
                          std::size_t& macLength) {
    HmacSha256Stream hmac(key);
    if (!hmac.usable()) return HmacStatus::kCryptoError;

    std::ifstream in(path, std::ios::binary | std::ios::in);
    if (!in) return HmacStatus::kReadError;

    std::array<char, 65536> buffer{};
    while (in.read(...)) { update... }
    if (in.bad()) return kReadError;
    if (in.gcount() > 0) { update }
    if (!hmac.finish(mac, macLength)) return kCryptoError;
    return kSuccess;
}
