And:

```cpp
// Stream standard input (file descriptor 0) into HMAC-SHA-256 until EOF.
// Selected by "--file -": every byte delivered before the end-of-input is
// part of the message, exactly as with a file -- zero bytes, trailing
// newlines and any line-ending forms are authenticated unchanged, and an
// empty input is the empty message. Only one fixed-size buffer is used no
// matter how long the input runs. A read error -- including one after a
// non-empty prefix has already been fed to HMAC -- aborts authentication:
// finish() is never called, so no partial-message tag can be produced.
HmacStatus hmacSha256Stdin(const std::vector<unsigned char>& key,
                           std::array<unsigned char, EVP_MAX_MD_SIZE>& mac,
                           std::size_t& macLength) {
    HmacSha256Stream hmac(key);
    if (!hmac.usable()) return HmacStatus::kCryptoError;

    std::array<char, 65536> buffer{};
    for (;;) {
        ssize_t n = ::read(STDIN_FILENO, buffer.data(), buffer.size());
        if (n > 0) {
            if (!hmac.update(buffer.data(), static_cast<std::size_t>(n)))
                return HmacStatus::kCryptoError;
            continue;
        }
        if (n == 0) break;          // clean end of input
        if (errno == EINTR) continue;  // interrupted before any byte arrived
        return HmacStatus::kReadError;
    }
    if (!hmac.finish(mac, macLength)) return HmacStatus::kCryptoError;
    return HmacStatus::kSuccess;
}
```

